// Percent composition: mass% of element X = (n_X * A_X) / M_molar * 100%.
// Compound family C_a H_b O_c (e.g. glucose-like). Sliders set subscripts a,c
// (carbon and oxygen counts); hydrogen fixed at 2*a (a CH2O-style unit).
const Ac = 12.011, Ah = 1.008, Ao = 15.999; // atomic masses g/mol
const a = Math.max(1, Math.round(P.a));   // # carbon
const c = Math.max(0, Math.round(P.c));   // # oxygen
const b = 2 * a;                          // # hydrogen (CH2O repeat)
const mC = a * Ac, mH = b * Ah, mO = c * Ao;
const M = Math.max(1e-6, mC + mH + mO);   // molar mass
const pC = mC / M * 100, pH = mH / M * 100, pO = mO / M * 100;
// animated stacked bar: a sweeping marker rides the cumulative boundaries
const x0 = 120, x1 = H.W - 60, y = H.H / 2, bh = 70;
const segs = [
  { p: pC, col: H.colors.accent, lab: "C" },
  { p: pH, col: H.colors.good, lab: "H" },
  { p: pO, col: H.colors.warn, lab: "O" }
];
let cx = x0;
for (const s of segs) {
  const w = (s.p / 100) * (x1 - x0);
  H.rect(cx, y - bh / 2, Math.max(0, w), bh, { fill: s.col, stroke: H.colors.bg, width: 1 });
  if (w > 24) H.text(s.lab + " " + s.p.toFixed(1) + "%", cx + w / 2, y, { color: H.colors.bg, size: 13, weight: 700, align: "center", baseline: "middle" });
  cx += w;
}
